import type { Key, MouseEventHandler, ReactNode } from 'react'
import { Icon } from '@/lib/icon'
import { cn } from '@/lib/utils'
import type { MenuEntry } from '../../navigation/Menu'
import { ListContainer, ListContainerItem, type ListContainerProps } from './ListContainer'
import { ListItemActions, ListItemContextMenu, ListItemHeading, ListItemMedia } from './ListItemParts'
import parts from './ListItemParts.module.css'
import styles from './StackedList.module.css'

export interface StackedListItem {
  /** A stable key. Without it the index is the key. */
  id?: Key
  /** An Avatar or an Icon before the text. Decorative: the title names the item. */
  media?: ReactNode
  /** What the item is: a person, a project, a file. A string also names the actions button. */
  title: ReactNode
  /** A line under the title: an email, a role, a path. */
  description?: ReactNode
  /** A Tag or Badge after the title, such as the item's status. */
  status?: ReactNode
  /** Facts at the end of the row, such as an owner or when it changed. Wraps under the text when the row is too narrow. */
  meta?: ReactNode
  /** Makes the title a link whose target is the whole row, with a chevron at the end. Keep links out of the other slots then: links cannot nest. */
  href?: string
  /** Runs when the link is followed. */
  onClick?: MouseEventHandler<HTMLAnchorElement>
  /** The row's actions: a ⋯ Menu at the end, and on a row without `href`, the same entries on right click or long press. */
  actions?: MenuEntry[]
}

export interface StackedListProps extends Omit<ListContainerProps, 'children'> {
  /** The rows, in the order to show them. */
  items: StackedListItem[]
}

/**
 * Records as rows: an avatar or icon, a title with a line under it, a
 * status, facts at the end, and a link to the record or a menu of actions.
 * It owns no data and no landmark: the page names the region around it.
 * The frame, dividers, footer and empty state are ListContainer's.
 */
export function StackedList({ items, ...props }: StackedListProps) {
  return (
    <ListContainer {...props}>
      {items.map((item, i) => (
        <ListItemContextMenu key={item.id ?? i} item={item}>
          <ListContainerItem className={cn(parts.target, styles.item)}>
            <ListItemMedia item={item} />
            <div className={styles.main}>
              <div className={styles.text}>
                <ListItemHeading item={item} />
                {item.description && <p className={parts.description}>{item.description}</p>}
              </div>
              {item.meta && <div className={parts.meta}>{item.meta}</div>}
            </div>
            {item.actions?.length ? (
              <ListItemActions item={item} index={i} />
            ) : (
              item.href && <Icon name="chevron-right" className={styles.chevron} />
            )}
          </ListContainerItem>
        </ListItemContextMenu>
      ))}
    </ListContainer>
  )
}

/* One record a row: media, the text, facts at the end, then a menu or a
   chevron. ListContainer pads the rows and draws the lines between them.
   The facts wrap under the text when the row runs out of room, so the
   list needs no breakpoint of its own. The parts it shares with Grid List
   (media, heading, link, menu) are ListItemParts'. */
.item {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.main {
  display: flex;
  flex: 1;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-1) var(--space-4);
  min-inline-size: 0;
}

.text {
  display: grid;
  flex: 1 1 auto;
  gap: var(--space-1);
  min-inline-size: 0;
}

.chevron {
  flex: none;
  inline-size: var(--icon-md);
  block-size: var(--icon-md);
  color: var(--muted-foreground);
}

import type { ReactElement } from 'react'
import { Icon } from '@/lib/icon'
import { Button } from '../../buttons/Button'
import { ContextMenu } from '../../navigation/ContextMenu'
import { Menu } from '../../navigation/Menu'
import type { StackedListItem } from './StackedList'
import styles from './ListItemParts.module.css'

/*
 * The parts Stacked List and Grid List draw the same way: media, the
 * heading with its link, the ⋯ menu and the right-click menu. Internal: not
 * a pattern of its own. The patterns import ListItemParts.module.css too:
 * `target` goes on the row or card, the box the link stretches over;
 * `description` and `meta` style those slots.
 */

export function ListItemMedia({ item }: { item: StackedListItem }) {
  return (
    item.media && (
      <span className={styles.media} aria-hidden="true">
        {item.media}
      </span>
    )
  )
}

/** The title, as a link stretched over the whole item when it has `href`, then the status. */
export function ListItemHeading({ item }: { item: StackedListItem }) {
  return (
    <p className={styles.heading}>
      {item.href ? (
        <a href={item.href} onClick={item.onClick} className={styles.link}>
          {item.title}
        </a>
      ) : (
        <span className={styles.title}>{item.title}</span>
      )}
      {item.status}
    </p>
  )
}

/** The ⋯ menu, above the stretched link so it gets the click; nothing without actions. `index` names an item whose title is not a string. */
export function ListItemActions({ item, index }: { item: StackedListItem; index: number }) {
  if (!item.actions?.length) return null
  return (
    <span className={styles.end}>
      <Menu
        align="end"
        items={item.actions}
        trigger={
          <Button
            variant="secondary"
            appearance="ghost"
            size="sm"
            isIconOnly
            aria-label={`Actions for ${typeof item.title === 'string' ? item.title : `item ${index + 1}`}`}
          >
            <Icon name="more" />
          </Button>
        }
      />
    </span>
  )
}

/**
 * The same actions on right click or long press. A linked item keeps the
 * browser's own link menu (open in new tab, copy link); the ⋯ button still
 * has the actions. The <li> itself is the area, so the list keeps only <li>
 * children.
 */
export function ListItemContextMenu({ item, children }: { item: StackedListItem; children: ReactElement }) {
  return item.actions?.length && !item.href ? <ContextMenu items={item.actions}>{children}</ContextMenu> : children
}

/* What Stacked List's rows and Grid List's cards share. The layout around
   these parts (row or card) stays in each pattern's own stylesheet. */

/* The row or card is the target, so hovering anywhere on it underlines the
   title. No background tint: muted text on a tint drops below 4.5:1. */
.target {
  position: relative;
}
.target:hover:not(:has(.end:hover)) .link {
  text-decoration: underline;
}

/* An Icon sits in a filled circle; an Avatar of the same size covers it. */
.media {
  display: grid;
  flex: none;
  place-items: center;
  inline-size: var(--avatar-md);
  block-size: var(--avatar-md);
  border-radius: var(--radius-full);
  background: var(--surface-filled);
  color: var(--muted-foreground);
}

.heading {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-1) var(--space-2);
  margin: 0;
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  font-weight: 500;
  min-inline-size: 0;
}

.title,
.link {
  min-inline-size: 0;
  overflow-wrap: anywhere;
}

/* The item is the target: the link's box stretches over the whole of it. */
.link {
  color: inherit;
  text-decoration: none;
}
.link::after {
  content: '';
  position: absolute;
  inset: 0;
}
.link:focus-visible {
  outline: none;
}
.link:focus-visible::after {
  outline: var(--focus-width) solid var(--ring);
  outline-offset: calc(var(--focus-width) * -1);
  /* A card sets this to follow its panel's corners. */
  border-radius: var(--list-item-focus-radius, 0);
}

.description,
.meta {
  margin: 0;
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  color: var(--muted-foreground);
  overflow-wrap: anywhere;
  min-inline-size: 0;
}

/* Above a linked item's stretched target, so the menu button gets the click. */
.end {
  position: relative;
  flex: none;
}
